# Canonical verse counts for continuity audit
verse_counts = {
    "Ezra": books["Ezra"]["counts"],
    "Nehemiah": books["Nehemiah"]["counts"],
    "Esther": books["Esther"]["counts"]
}

manifest = []
for book_name, details in books.items():
    panels = []
    audit_errors = []
    panel_id = 1
    chapters = details["chapters"]
    for ch in range(1, max(details["counts"]) + 1):
        segs = chapters.get(ch)
        if not segs:
            audit_errors.append(f"{book_name} missing chapter {ch}")
            continue
        expected_start = 1
        for seg in segs:
            ch_num = seg["chapter"]
            verse_range = seg["verses"]
            m = re.fullmatch(rf"{ch_num}:(\d+)(?:-(\d+))?", verse_range)
            if not m:
                audit_errors.append(f"{book_name} bad range: {verse_range}")
                continue
            start = int(m.group(1))
            end = int(m.group(2) or start)
            if start != expected_start:
                audit_errors.append(f"{book_name} {ch}: expected verse {expected_start}, got {start}")
            if end < start:
                audit_errors.append(f"{book_name} {ch}: reversed range {verse_range}")
            expected_start = end + 1
            panels.append({
                "panel_id": panel_id,
                "book": book_name,
                "chapter": ch_num,
                "verses": verse_range,
                "title": seg["title"],
                "image_prompt": seg["image_prompt"]
            })
            panel_id += 1
        if expected_start - 1 != details["counts"][ch]:
            audit_errors.append(
                f"{book_name} {ch}: ended at {expected_start-1}, expected {details['counts'][ch]}"
            )

    assert not audit_errors, "\n".join(audit_errors)
    assert len(panels) == len({p["panel_id"] for p in panels})
    assert all(list(p.keys()) == [
        "panel_id", "book", "chapter", "verses", "title", "image_prompt"
    ] for p in panels)

    serialized = json.dumps(panels, ensure_ascii=False, indent=4)
    # Independently parse serialized JSON and audit chapter coverage again
    loaded = json.loads(serialized)
    for ch, total in details["counts"].items():
        curr = 1
        for p in [x for x in loaded if x["chapter"] == ch]:
            m = re.fullmatch(rf"{ch}:(\d+)(?:-(\d+))?", p["verses"])
            assert m, (book_name, p["verses"])
            st = int(m.group(1))
            en = int(m.group(2) or st)
            assert st == curr, (book_name, ch, p["verses"], curr)
            curr = en + 1
        assert curr == total + 1, (book_name, ch, curr, total)

    path = os.path.join(OUTDIR, details["filename"])
    with open(path, "w", encoding="utf-8") as f:
        f.write(serialized)
    manifest.append((details["filename"], len(panels), path))

for fname, count, path in manifest:
    print(f"Created {fname}: {count} panels; continuous verse coverage verified for every chapter.")
print("All three JSON files are valid arrays with exactly the six required fields.")